def _cast_empty_df_dtypes(schema_fields, df):
    """Cast any columns in an empty dataframe to correct type.

    In an empty dataframe, pandas cannot choose a dtype unless one is
    explicitly provided. The _bqschema_to_nullsafe_dtypes() function only
    provides dtypes when the dtype safely handles null values. This means
    that empty int64 and boolean columns are incorrectly classified as
    ``object``.
    """
    for field in schema_fields:
        if field.name not in df.columns:
            continue
        if field.field_type == "RECORD":
            continue
        if field.field_type == "STRING":
            df[field.name] = df[field.name].astype("object")
        elif field.field_type == "INTEGER":
            df[field.name] = df[field.name].astype("Int64")
        elif field.field_type == "FLOAT":
            df[field.name] = df[field.name].astype("float")
        elif field.field_type == "BOOLEAN":
            df[field.name] = df[field.name].astype("bool")
        elif field.field_type == "TIMESTAMP":
            df[field.name] = df[field.name].astype("datetime64[ns]")
        elif field.field_type == "DATE":
            df[field.name] = df[field.name].astype("datetime64[ns]")
        elif field.field_type == "TIME":
            df[field.name] = df[field.name].astype("timedelta64[ns]")
        elif field.field_type == "BYTES":
            df[field.name] = df[field.name].astype("bytes")
        elif field.field_type == "NUMERIC":
            df[field.name] = df[field.name].astype("object")
        elif field.field_type == "GEOGRAPHY":
            df[field.name] = df[field.name].astype("object")
        elif field.field_type == "ARRAY":
            df[field.name] = df[field.name].astype("object")
        elif field.field_type == "STRUCT":
            df[field.name] = df[field.name].astype("object")
        else:
            raise ValueError(f"Unknown field type: {field.field_type}")
    return df

